INSERT INTO dump_descriptions (base_key, description) VALUES ('cd1-client', 'Enables the CD1 custom-difficulty framework when you join a lobby running CD1; it does nothing in other lobbies and works without the original CD1 pak.') ON CONFLICT(base_key) DO UPDATE SET description=excluded.description, updated_at=CURRENT_TIMESTAMP;
INSERT INTO dump_descriptions (base_key, description) VALUES ('lightalloycomponents_english', 'English text translation for Flying Dickcat’s Light Alloy Components Minigun overclocks; the author says the Chinese text was translated with Google Translate and guesswork.') ON CONFLICT(base_key) DO UPDATE SET description=excluded.description, updated_at=CURRENT_TIMESTAMP;
INSERT INTO dump_descriptions (base_key, description) VALUES ('muzzleflash_smoke_adjustments_mercy_special', 'Tones down most visually intrusive weapon effects; Gunner primary-weapon effects are changed less than the others.') ON CONFLICT(base_key) DO UPDATE SET description=excluded.description, updated_at=CURRENT_TIMESTAMP;
INSERT INTO dump_descriptions (base_key, description) VALUES ('nocarve121', 'Disables terrain carving from a bundle of weapons and explosives, including the PGL, Autocannon, Hurricane Mortar Rounds, Bulldog, and several grenades.') ON CONFLICT(base_key) DO UPDATE SET description=excluded.description, updated_at=CURRENT_TIMESTAMP;
INSERT INTO dump_descriptions (base_key, description) VALUES ('remove-all-muzzle-flashes', 'Removes weapon muzzle flashes when used with Remove All Particles but Weapons.') ON CONFLICT(base_key) DO UPDATE SET description=excluded.description, updated_at=CURRENT_TIMESTAMP;
INSERT INTO dump_descriptions (base_key, description) VALUES ('sandboxutilities_cd2b10b', 'Adds Custom Difficulty 2 descriptor support to AssemblyStorm’s Sandbox Utilities pak; it can replace the original Sandbox Utilities pak.') ON CONFLICT(base_key) DO UPDATE SET description=excluded.description, updated_at=CURRENT_TIMESTAMP;
INSERT INTO dump_descriptions (base_key, description) VALUES ('simpleiconcolor_whitefix', 'Removes gradient backgrounds and border bars from HUD elements such as the ammo bar.') ON CONFLICT(base_key) DO UPDATE SET description=excluded.description, updated_at=CURRENT_TIMESTAMP;
INSERT INTO dump_descriptions (base_key, description) VALUES ('woh_cd2', 'Ports Wrath of Hoxxes enemy content to Custom Difficulty 2 by moving its enemy descriptors to a visible location and removing them from the pool.') ON CONFLICT(base_key) DO UPDATE SET description=excluded.description, updated_at=CURRENT_TIMESTAMP;
INSERT INTO dump_descriptions (base_key, description) VALUES ('opaque_crosshair-updated_for_s5', 'Replicates the Opaque Crosshair mod for Season 5.') ON CONFLICT(base_key) DO UPDATE SET description=excluded.description, updated_at=CURRENT_TIMESTAMP;
INSERT INTO dump_descriptions (base_key, description) VALUES ('reduce_mining_fragments', 'Reduces pebble debris from power drilling and from mining minerals and metals; the author excludes Hollow Bough and Fungus Bogs.') ON CONFLICT(base_key) DO UPDATE SET description=excluded.description, updated_at=CURRENT_TIMESTAMP;
INSERT INTO dump_descriptions (base_key, description) VALUES ('reduce_mining_fragments_minimal_dust', 'Reduces mining debris and uses the minimal-dust variant.') ON CONFLICT(base_key) DO UPDATE SET description=excluded.description, updated_at=CURRENT_TIMESTAMP;
INSERT INTO dump_descriptions (base_key, description) VALUES ('reduce_mining_fragments_minimal_dust__sparks', 'Reduces mining debris with minimal dust and sparks.') ON CONFLICT(base_key) DO UPDATE SET description=excluded.description, updated_at=CURRENT_TIMESTAMP;
INSERT INTO dump_descriptions (base_key, description) VALUES ('reduce_mining_fragments_minimal_dust_zero_sparks', 'Reduces mining debris with minimal dust and removes the sparks.') ON CONFLICT(base_key) DO UPDATE SET description=excluded.description, updated_at=CURRENT_TIMESTAMP;
INSERT INTO dump_descriptions (base_key, description) VALUES ('reduce_mining_fragments_zero_dust__sparks', 'Reduces mining debris and removes dust while retaining the spark effect.') ON CONFLICT(base_key) DO UPDATE SET description=excluded.description, updated_at=CURRENT_TIMESTAMP;
